"""Freeze the isolated material study separately from parent production captures."""
from pathlib import Path
import hashlib,json,re,subprocess
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[4]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def rel(p):return str(Path(p).relative_to(ROOT)).replace('\\','/')
def read(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def main():
    builder=ROOT/'scripts/terrain/frontier_closed_buildings.gd';shader=ROOT/'shaders/terrain/frontier_building_wear.gdshader'
    qa=read(HERE/'qa/geometry_raw.json');response=read(HERE/'qa/render_response.json')
    assert qa['passed']==39 and qa['failed']==0 and response['passed']==6 and response['failed']==0
    assert sha(builder)==qa['builder_sha256']==sha(HERE/'source/frontier_closed_buildings_pass06.gd')
    assert sha(shader)==qa['shader_sha256']==sha(HERE/'source/frontier_building_wear.gdshader')
    assert all(v['geometry_identical'] and v['per_part_bounds_valid'] and v['exempt_materials_preserved'] and v['translated_origin_valid'] for v in qa['material_diagnostics'])
    for f in ['material_geometry_check.log','native_probe.log','native_probe.err']:
        assert not re.search(r'SCRIPT ERROR|\bERROR:|Parse Error|leaked at exit',(HERE/'qa'/f).read_text(encoding='utf-8-sig')),f
    assert subprocess.run(['git','diff','--quiet','--','scripts/terrain/frontier_art_profile.gd'],cwd=ROOT).returncode==0
    views=read(HERE/'qa/native_views.json');assert len(views)==15
    for key in [(v['building'],v['view']) for v in views if v['revision']=='after']:
        group=[v for v in views if (v['building'],v['view'])==key]
        assert len(group)==3 and len({(v['camera'],v['size'],v['resolution']) for v in group})==1
    for v in views:
        p=ROOT/v['path'].removeprefix('res://');v.update({'path':rel(p),'sha256':sha(p),'opened':True})
    refs=ROOT/'docs/reports/assets/grafik-2026-11-01'
    references=[{'path':rel(refs/p),'sha256':sha(refs/p)} for p in ['references/current/01_rostgrenze_cutaway.png','references/current/02_freihafen_distribution_center.png','engine_pass05_environment/after/closed_habitat.png','engine_pass05_environment/after/closed_hall.png']]
    assets=[]
    for geometry in qa['diagnostics']:
        materials=next(m for m in qa['material_diagnostics'] if m['id']==geometry['id'])
        assets.append({'id':geometry['id'],'geometry':geometry,'materials':materials,'geometry_change':False})
    out={'schema':'sternenbuergerchen.pass06_building_wear.v1','task':'docs/tasks/ART_2026_11_01_pass06_environment.md','status':'material candidate frozen for parent integration; no artistic user approval','runtime_sources':[{'path':rel(p),'sha256':sha(p)} for p in [builder,shader]],'before_builder':{'path':rel(HERE/'source/frontier_closed_buildings_before.gd'),'sha256':sha(HERE/'source/frontier_closed_buildings_before.gd')},'editable_sources':['source/frontier_closed_buildings_pass06.gd','source/frontier_building_wear.gdshader'],'assets':assets,'references_opened':references,'material_route':{'painted_surfaces':'Shared ShaderMaterial per original color and semantic role (paint, roof, structure, base); building-relative static fields, local component AABB instance uniforms for selected edge wear.','preserved':'Original StandardMaterial3D color/energy route for glass, emissive strips/windows, narrow graphic markings and deep gaps; numeric properties checked against P05.','wear_hierarchy':'Metre-scale soft pigment and broad faded upper fields; weaker middle brush scale; base dust and sparse long facade wash; only selected physical edges receive small dark undercoat scuffs.','visual_adjustment':'First opened native study too faint. Broad/middle amplitude increased0.22/0.065 to0.38/0.075; upper bleaching and base dust increased with all noise frequencies unchanged.','strength_zero_control':'Same new shader route with wear_strength0 matches P05 StandardMaterial rendering nearly exactly; direct numerical evidence retained.'},'preserved_contract':{'geometry':'All generated mesh arrays and transforms match P05 SHA256 fingerprints, including normals and indices.','bounds':'P05 AABBs unchanged including signs; original XZ+0.22m and height+0.20m retained.','visibility':'all parts remain under same existing closed/cutaway root; no process/update loop added','lights_and_gameplay':'No lighting/environment, collision/nav, door/interior, simulation or source-asset change.','shader_motion':'No vertex displacement, normal perturbation or TIME-driven animation.'},'qa':{'driver':rel(HERE/'look_probe.gd'),'success_marker':'BUILDING_PASS06_QA','passed':39,'failed':0,'raw':rel(HERE/'qa/geometry_raw.json'),'render_response':response,'scope':qa['scope'],'limits':'AABB connectivity remains conservative, not an exact intersection/zfight oracle. Checks and image deltas do not imply artistic approval or general performance/release acceptance.'},'isolated_native_views':views,'visual_review':{'opened':True,'findings':'Compared same-camera P05/zero-wear/after images. Broad roof fading and warmer lower dust now visibly break the clean uniform fields; sparse downward marks appear on selected fascia zones. Original silhouette, glass, signs and warm lights remain readable.','remaining_differences':'Still much cleaner and less individually painted than the rich illustrations; edge chips are intentionally sparse and remain small at game distance. No sculpted corrosion/depth or texture-authoring pass.','probe_limitation':'The isolated probe has fine checker/shadow-dither visible in the background and both old/new states. It is not a new wear pattern; parent combined native captures do not show it and remain the main visual evidence.','acceptance':'candidate review only, not user art acceptance'},'production_capture':'Parent owns combined scene captures/strict suite/report and frozen model-hash verification. This package does not claim those as performed here.','scope':['scripts/terrain/frontier_closed_buildings.gd','shaders/terrain/frontier_building_wear.gdshader','art/frontier_illustrated_20261101/environment/pass06/buildings/'],'not_changed_by_this_subtask':['geometry','Kenney/Citizen/ship GLBs','preview/renderer/dressing/tests/reports','global light/environment','imports/commits/pushes'],'branch':'task/grafikreferenzen-20261101, intentional continuation of the unintegrated graphics branch'}
    (HERE/'manifest.json').write_text(json.dumps(out,indent=2),encoding='utf-8');print(json.dumps({'manifest':rel(HERE/'manifest.json'),'sources':out['runtime_sources'],'passed':39,'render_response_passed':6,'opened_native_views':15}))
if __name__=='__main__':main()
